const fs=require("fs");
const dir="/tmp/neutrino-fast-live-LY3jZs/multi_source_retrieval/standard/0";
const files=["a.txt","b.txt","c.txt"];
let sum=0; const seen=new Set();
for(const f of files){
  const p=dir+"/"+f;
  const lines=fs.readFileSync(p,"utf8").split(/\r?\n/).filter(l=>l.trim()!=="");
  if(lines.length!==1){console.error("FAIL "+p+": expected exactly 1 non-empty line, got "+lines.length);process.exit(1);}
  const m=lines[0].match(/^\s*([A-Za-z][A-Za-z ]*?)\s+population:\s*(\d+)\s*$/i);
  if(!m){console.error("FAIL "+p+": unparsable line "+JSON.stringify(lines[0]));process.exit(1);}
  const name=m[1].trim(); const val=Number(m[2]);
  if(seen.has(name)){console.error("FAIL duplicate population label "+name);process.exit(1);}
  seen.add(name);
  console.log("CHECKED "+p+" -> "+name+" population = "+val);
  sum+=val;
}
console.log("RECOMPUTED TOTAL = "+sum);
const ansPath=dir+"/answer.json";
const raw=fs.readFileSync(ansPath,"utf8");
let ans; try{ans=JSON.parse(raw);}catch(e){console.error("FAIL answer.json does not parse: "+e.message);process.exit(1);}
const keys=Object.keys(ans);
if(keys.length!==1||keys[0]!=="total"){console.error("FAIL answer.json keys = "+JSON.stringify(keys));process.exit(1);}
if(typeof ans.total!=="number"||!Number.isFinite(ans.total)){console.error("FAIL total is not a finite number: "+JSON.stringify(ans.total));process.exit(1);}
console.log("answer.json parsed: "+raw.trim());
if(ans.total!==sum){console.error("FAIL total "+ans.total+" != recomputed "+sum);process.exit(1);}
console.log("MATCH: answer.json total === recomputed sum ("+ans.total+")");
console.log("VERIFICATION PASSED");
'
